// Draft: the specification is not approved: there is no records/approvals/0.1.0.yaml beside the specification; this file is not the approved output.
// The application's menu from config/menus.js, each entry shown only to
// someone its page opens to, and no empty group.

import { menus } from "../config/menus.js";
import { visibleMenu } from "./access.js";
import { Link, location } from "./router.js";
import { useSession } from "./session.js";
import { say } from "./texts.js";
import { html } from "./vue.js";

export const Menu = {
  name: "Menu",
  props: { texts: { type: Object, required: true } },
  setup(props) {
    const session = useSession();
    return () => {
      if (!session.value) {
        return null;
      }
      const groups = visibleMenu(menus, session.value);
      if (groups.length === 0) {
        return null;
      }
      return html`<nav class="screens-menu" aria-label=${say(props.texts, "screens.menu")}>
        <ul>
          ${groups.map(
            (group) => html`<li key=${group.title}>
              <span class="screens-menu-group">${say(props.texts, group.title)}</span>
              <ul>
                ${group.items.map(
                  (item) =>
                    html`<li key=${item.route}><${Link} to=${item.route} aria-current=${location.value.path === item.route ? "page" : undefined}>${say(props.texts, item.title)}<//></li>`,
                )}
              </ul>
            </li>`,
          )}
        </ul>
      </nav>`;
    };
  },
};
